#pragma once

// Callee tables zx-fncheck is built with beyond fncheck_build.h's (in a header
// of their own, which the traced originals do not include: a change here
// rebuilds only zx-fncheck). Generated by tools/readable/fncheck_traced_gen.py.

#include "fncheck_build.h"

namespace fncheck
{
    // Functions a caller reads f0 after (some call site reads $f0 before setting
    // it, straight after the call): a readable version typed as returning an
    // integer must leave f0 as the original does (the int_f0 class).
    struct F0Reader
    {
        uint8_t game;
        uint32_t function;
    };
    extern const F0Reader g_f0Readers[];
    extern const size_t g_f0ReaderCount;

    // The argument registers each function reads before it sets them on some
    // path, its callees' and tail calls' reads of the registers it leaves
    // included (bits 0-7: a0-a3, t0-t3; 8-15: f12-f19); handed: those it
    // hands on unchanged to a callee the scan cannot name (an indirect call
    // or tail call, a kernel call), directly or through a callee that does:
    // zx-fncheck notes a readable call that leaves out one of either with
    // another value than the original passed (args_left; for a game::call of a
    // readable callee also direct_left; drafter25).
    struct ArgReader
    {
        uint8_t game;
        uint32_t function;
        uint16_t reads;
        uint16_t handed;
    };
    extern const ArgReader g_argReaders[];
    extern const size_t g_argReaderCount;

    // The registers some caller reads after calling a function, before it sets
    // them (a straight-line scan of every jal's return; a wrapper that returns
    // with the register untouched and a tail caller hand on their own callers'
    // reads): gprs bit r for GPR r (at, v0, v1, a0-a3, t0-t9), fprs bit i for
    // f_i (f0-f19). A readable version must leave those as the original does:
    // f0 of an integer function and v0 of a void one fail the check, the
    // others are noted (regs_left).
    struct ResultReader
    {
        uint8_t game;
        uint32_t function;
        uint32_t gprs;
        uint32_t fprs;
    };
    extern const ResultReader g_resultReaders[];
    extern const size_t g_resultReaderCount;

    // The VU0 lanes that cross a function boundary (fncheck_traced_gen.py's
    // vu0_lanes; bit r * 4 + l of the two words for vf<r>, l 0 x .. 3 w).
    // atEntry: what the function reads before it sets it, its callees' reads
    // included. atReturn: what is live when it returns. A row with function 0:
    // what is live after some indirect call, at every function's return.
    struct Vu0Lanes
    {
        uint8_t game;
        uint32_t function;
        uint64_t atEntry[2];
        uint64_t atReturn[2];
    };
    extern const Vu0Lanes g_vu0Lanes[];
    extern const size_t g_vu0LanesCount;

    // Each traced function's entry blocks (the addresses the function table
    // maps to an entry_ function): flags 1, 3 when a branch back of the
    // function goes there (a loop head). Sorted by (game, function, address).
    // zx-fncheck --markers lists the ones the replayed calls reach that the
    // readable version never marks (ee/markers.h).
    struct SafePointMark
    {
        uint8_t game;
        uint32_t function;
        uint32_t address;
        uint8_t flags;
    };
    extern const SafePointMark g_safePointMarks[];
    extern const size_t g_safePointMarkCount;

    // Functions whose generated code goes into the runtime's own code (a
    // library function the runtime implements, a syscall or exception
    // instruction), which touches guest memory and the kernel's state without
    // telling a tracer: zx-fncheck's callee probes stop before running one.
    struct UntracedCode
    {
        uint8_t game;
        uint32_t function;
    };
    extern const UntracedCode g_untracedCode[];
    extern const size_t g_untracedCodeCount;
}
